<?php
require 'db.php'; require 'helpers.php'; require_admin();
$msg=''; @mkdir(__DIR__.'/uploads',0755,true);
if ($_SERVER['REQUEST_METHOD']==='POST') {
    csrf_check(); $act=$_POST['action']??''; $id=(int)($_POST['id']??0);
    if ($act==='delete' && $id>0) {
        $s=$pdo->prepare('SELECT event_name FROM events WHERE id=? AND deleted_at IS NULL'); $s->execute([$id]); $ev=$s->fetch();
        if($ev){$pdo->prepare('UPDATE events SET deleted_at=NOW() WHERE id=?')->execute([$id]);audit($pdo,'event_delete_to_trash','Event ID '.$id.' ('.$ev['event_name'].') moved to trash; registrations retained');$msg='Event moved to Deleted Events. You can restore it.';}else $msg='Active event not found.';
    } elseif ($act==='restore' && $id>0) {
        $s=$pdo->prepare('SELECT event_name FROM events WHERE id=? AND deleted_at IS NOT NULL');$s->execute([$id]);$ev=$s->fetch();
        if($ev){$pdo->prepare('UPDATE events SET deleted_at=NULL WHERE id=?')->execute([$id]);audit($pdo,'event_restore','Restored event ID '.$id.' ('.$ev['event_name'].')');$msg='Event restored successfully.';}else $msg='Deleted event not found.';
    } elseif ($act==='permanent_delete' && $id>0) {
        $s=$pdo->prepare('SELECT event_name,poster FROM events WHERE id=? AND deleted_at IS NOT NULL');$s->execute([$id]);$ev=$s->fetch();
        if($ev){try{$pdo->beginTransaction();$pdo->prepare('DELETE FROM events WHERE id=?')->execute([$id]);$pdo->commit();if($ev['poster'] && is_file(__DIR__.'/uploads/'.$ev['poster'])) @unlink(__DIR__.'/uploads/'.$ev['poster']);audit($pdo,'event_permanent_delete','Permanently deleted event ID '.$id.' ('.$ev['event_name'].'); registrations cascade');$msg='Event permanently deleted. This cannot be undone.';}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$msg='Permanent delete failed: '.$e->getMessage();}}else $msg='Event not found in Deleted Events.';
    } elseif ($act==='save') {
        $id=(int)($_POST['id']??0);$name=trim($_POST['event_name']??'');$date=$_POST['event_date']??'';$venue=trim($_POST['venue']??'');$category=trim($_POST['category']??'General')?:'General';$desc=trim($_POST['description']??'');$status=($_POST['status']??'open')==='closed'?'closed':'open';$poster=null;
        if(!empty($_FILES['poster']['name'])){$f=$_FILES['poster'];$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];$mime=($f['error']===UPLOAD_ERR_OK)?(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']):'';if($f['error']!==UPLOAD_ERR_OK||$f['size']>2*1024*1024||!isset($allowed[$mime]))$msg='Poster must be JPG/PNG/WEBP and maximum 2 MB.';else{$poster=bin2hex(random_bytes(12)).'.'.$allowed[$mime];if(!move_uploaded_file($f['tmp_name'],__DIR__.'/uploads/'.$poster)){$poster=null;$msg='Could not save the uploaded poster.';}}}
        if(!$msg && $name && $date && $venue){
            if($id){if($poster){$old=$pdo->prepare('SELECT poster FROM events WHERE id=? AND deleted_at IS NULL');$old->execute([$id]);$oldPoster=$old->fetchColumn();$s=$pdo->prepare('UPDATE events SET event_name=?,event_date=?,venue=?,category=?,description=?,status=?,poster=? WHERE id=? AND deleted_at IS NULL');$s->execute([$name,$date,$venue,$category,$desc,$status,$poster,$id]);if($oldPoster&&is_file(__DIR__.'/uploads/'.$oldPoster))@unlink(__DIR__.'/uploads/'.$oldPoster);}else{$s=$pdo->prepare('UPDATE events SET event_name=?,event_date=?,venue=?,category=?,description=?,status=? WHERE id=? AND deleted_at IS NULL');$s->execute([$name,$date,$venue,$category,$desc,$status,$id]);}$msg='Event updated.';audit($pdo,'event_update','Event ID '.$id.' ('.$name.')');}
            else{$s=$pdo->prepare('INSERT INTO events(event_name,event_date,venue,category,description,status,poster) VALUES(?,?,?,?,?,?,?)');$s->execute([$name,$date,$venue,$category,$desc,$status,$poster]);$msg='Event added.';audit($pdo,'event_create',$name);}
        } elseif(!$msg) $msg='Please complete event name, date and venue.';
    }
}
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM events WHERE id=? AND deleted_at IS NULL');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch()?:null;}
$rows=$pdo->query('SELECT * FROM events WHERE deleted_at IS NULL ORDER BY event_date DESC')->fetchAll();
$deletedRows=$pdo->query('SELECT * FROM events WHERE deleted_at IS NOT NULL ORDER BY deleted_at DESC LIMIT 200')->fetchAll();
page_header('Manage Events');if($msg)echo '<div class="notice">'.e($msg).'</div>';
?>
<section class="panel"><h2><?= $edit?'Edit Event':'Add Event' ?></h2><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e($edit['id']??0)?>"><label>Event name</label><input name="event_name" required value="<?=e($edit['event_name']??'')?>"><label>Date</label><input type="date" name="event_date" required value="<?=e($edit['event_date']??'')?>"><label>Venue</label><input name="venue" required value="<?=e($edit['venue']??'')?>"><label>Category</label><input name="category" value="<?=e($edit['category']??'General')?>"><label>Description</label><textarea name="description"><?=e($edit['description']??'')?></textarea><label>Status</label><select name="status"><option value="open" <?=($edit['status']??'open')==='open'?'selected':''?>>Open</option><option value="closed" <?=($edit['status']??'')==='closed'?'selected':''?>>Closed</option></select><label>Poster (JPG/PNG/WEBP, max 2MB)</label><input type="file" name="poster" accept="image/jpeg,image/png,image/webp"><?php if(!empty($edit['poster'])):?><p>Current poster: <?=e($edit['poster'])?></p><?php endif;?><button><?= $edit?'Update Event':'Add Event' ?></button><?php if($edit):?> <a class="btn" href="event_manage.php">Cancel edit</a><?php endif;?></form></section>
<section class="panel"><h2>Active Events</h2><table><tr><th>Name</th><th>Date</th><th>Venue</th><th>Status</th><th>Actions</th></tr><?php if(!$rows):?><tr><td colspan="5">No active events.</td></tr><?php endif;?><?php foreach($rows as $r):?><tr><td><?=e($r['event_name'])?></td><td><?=e($r['event_date'])?></td><td><?=e($r['venue'])?></td><td><?=e($r['status'])?></td><td><a class="btn" href="event_manage.php?edit=<?=$r['id']?>">Edit</a> <form method="post" style="display:inline-block" onsubmit="return confirm('Move this event to Deleted Events? It can be restored.')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button>Delete</button></form></td></tr><?php endforeach;?></table></section>
<section class="panel"><h2>Deleted Events / Restore</h2><p>Deleted events are hidden from students, while registrations are kept until you permanently delete the event.</p><table><tr><th>Name</th><th>Date</th><th>Venue</th><th>Deleted at</th><th>Actions</th></tr><?php if(!$deletedRows):?><tr><td colspan="5">No deleted events.</td></tr><?php endif;?><?php foreach($deletedRows as $r):?><tr><td><?=e($r['event_name'])?></td><td><?=e($r['event_date'])?></td><td><?=e($r['venue'])?></td><td><?=e($r['deleted_at'])?></td><td><form method="post" style="display:inline-block"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="restore"><input type="hidden" name="id" value="<?=$r['id']?>"><button>Restore Event</button></form> <form method="post" style="display:inline-block" onsubmit="return confirm('Permanently delete this event and all its registrations? This cannot be undone.')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="permanent_delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn-danger">Permanently Delete</button></form></td></tr><?php endforeach;?></table></section>
<?php page_footer(); ?>
